const items = $input.first().json.results || [];

const now = new Date();
const t7d = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));
const t15d = new Date(now.getTime() - (15 * 24 * 60 * 60 * 1000));
const t30d = new Date(now.getTime() - (30 * 24 * 60 * 60 * 1000));

let total = items.length;
let active = 0;
let completed = 0;
let completed7d = 0;
let completed15d = 0;
let completed30d = 0;
let backlogConquered = 0;
let backlogActive = 0;
let unassigned = 0;
let inReview = 0;
let earnedWeight = 0;
let totalWeight = 0;
let podDistribution = {};

const priorityWeights = {'P1 - Urgent': 500, 'P2 - High': 250, 'P3 - Medium': 100, 'P4 - Low': 25};

for (const item of items) {
  const props = item.properties || {};
  const status = props['Status']?.status?.name || 'To Do';
  const isDone = (status === 'Done' || status === 'Archived');
  const bState = props['Backlog State']?.formula?.string || '';
  const assignees = props['Assignee']?.people || [];
  const pod = props['Team / Pod']?.select?.name || 'General';
  const priority = props['Priority']?.select?.name || 'P3 - Medium';
  const compStr = props['Complexity']?.select?.name || '3';
  const stars = parseInt(compStr.replace(/[^0-9]/g, '') || '3', 10);
  const taskWeight = (priorityWeights[priority] || 100) * stars;

  totalWeight += taskWeight;

  if (isDone) {
    completed++;
    earnedWeight += taskWeight;
    if (bState === '🏆 Conquered Backlog Debt' || props['Original Backlog Item']?.checkbox === true) {
      backlogConquered++;
    }

    const compDateStr = props['Completed At']?.date?.start;
    if (compDateStr) {
      const compDate = new Date(compDateStr);
      if (compDate >= t7d) completed7d++;
      if (compDate >= t15d) completed15d++;
      if (compDate >= t30d) completed30d++;
    } else {
      completed7d++;
      completed15d++;
      completed30d++;
    }
  } else {
    active++;
    if (bState === '⚠️ Rolled-Over Backlog Debt' || status === 'Backlog') backlogActive++;
    if (assignees.length === 0) unassigned++;
    if (status === 'In Review') inReview++;
    podDistribution[pod] = (podDistribution[pod] || 0) + 1;
  }
}

const completionRate = total > 0 ? ((completed / total) * 100).toFixed(1) : 0;
const waspScore = total > 0 ? Math.min(100, Math.round((earnedWeight / (totalWeight || 1)) * 65 + (completed / total) * 35)) : 100;

// Build Google Chat Card v2 Payload
const googleChatPayload = {
  cardsV2: [
    {
      cardId: 'wasp_admin_weekly_digest_' + Date.now(),
      card: {
        header: {
          title: '🐝 WASP Engine — Weekly Executive Digest',
          subtitle: `Sprint Velocity & Profile Accountability Recap (${now.toISOString().split('T')[0]})`,
          imageUrl: 'https://cdn-icons-png.flaticon.com/512/1828/1828884.png',
          imageType: 'CIRCLE'
        },
        sections: [
          {
            header: '⚡ Multi-Horizon Throughput & WASP Index',
            widgets: [
              {
                decoratedText: {
                  topLabel: 'WASP Performance Index',
                  text: `<b>${waspScore} / 100 Points</b>`,
                  bottomLabel: `${earnedWeight} / ${totalWeight} Weighted Priority Pts`
                }
              },
              {
                decoratedText: {
                  topLabel: '7-Day Sprint Output',
                  text: `<b>${completed7d} Tasks Delivered</b>`,
                  bottomLabel: 'Sprint velocity output'
                }
              },
              {
                decoratedText: {
                  topLabel: '15-Day Mid-Cycle & Monthly',
                  text: `<b>15d: ${completed15d} | 30d: ${completed30d} Tasks</b>`,
                  bottomLabel: `Total Conquered: ${completed}/${total} (${completionRate}%)`
                }
              }
            ]
          },
          {
            header: '🏆 Backlog Analytics & Team Capacity',
            widgets: [
              {
                decoratedText: {
                  topLabel: 'Conquered Backlog Debt',
                  text: `<b>${backlogConquered} Debt Items Cleared</b>`,
                  bottomLabel: `Active Rollover Debt: ${backlogActive}`
                }
              },
              {
                decoratedText: {
                  topLabel: 'Active Workload & In Review',
                  text: `<b>${active - unassigned} Assigned | ${unassigned} Open Pool</b>`,
                  bottomLabel: `In Peer Review: ${inReview}`
                }
              },
              {
                buttonList: {
                  buttons: [
                    {
                      text: 'OPEN WASP DASHBOARD',
                      onClick: {
                        openLink: {
                          url: 'https://app.notion.com/p/WASP-Dashboard-Work-Analysis-System-Profile-Dashboard-3fff1bcff9b88188b004f044be8090fe'
                        }
                      }
                    }
                  ]
                }
              }
            ]
          }
        ]
      }
    }
  ]
};

const emailHtml = `
<h2>🐝 WASP Engine: Weekly Executive Digest</h2>
<p><b>Executive Recap for week ending ${now.toDateString()}:</b></p>
<table border="1" cellpadding="8" style="border-collapse:collapse;width:100%;font-family:sans-serif;">
  <tr style="background:#f3f4f6;"><th>WASP Dimension</th><th>Metric Value</th><th>Operational Context</th></tr>
  <tr><td>🐝 <b>WASP Performance Index</b></td><td><b>${waspScore} / 100 Pts</b></td><td>Weighted Priority & Velocity score</td></tr>
  <tr><td>⚡ <b>7-Day Sprint Output</b></td><td><b>${completed7d} Tasks</b></td><td>Immediate sprint delivery pace</td></tr>
  <tr><td>🗓️ <b>15-Day Mid-Cycle</b></td><td><b>${completed15d} Tasks</b></td><td>Bi-weekly velocity trajectory</td></tr>
  <tr><td>📈 <b>Monthly Throughput</b></td><td><b>${completed30d} Tasks</b></td><td>30-day cumulative execution</td></tr>
  <tr><td>🏆 <b>Conquered Backlog Debt</b></td><td><b>${backlogConquered} Items</b></td><td>Legacy technical debt paid down</td></tr>
  <tr><td>⚠️ <b>Rolled-Over Backlog Debt</b></td><td><b>${backlogActive} Items</b></td><td>Tasks that missed target End Dates</td></tr>
  <tr><td>👥 <b>Team Workload</b></td><td>${active - unassigned} Assigned / ${unassigned} Open</td><td>${inReview} in peer review</td></tr>
</table>
<p><a href="https://app.notion.com/p/WASP-Dashboard-Work-Analysis-System-Profile-Dashboard-3fff1bcff9b88188b004f044be8090fe" style="background:#2383e2;color:#fff;padding:8px 16px;text-decoration:none;border-radius:4px;font-weight:bold;">Open Live WASP Dashboard</a></p>
`;

return [{
  json: {
    waspScore,
    completed7d,
    completed15d,
    completed30d,
    backlogConquered,
    googleChatPayload,
    emailHtml
  }
}];
